SELECT analytics_order_facts.customer_segment, COUNT(DISTINCT analytics_order_facts.order_id) AS order_count FROM analytics_order_facts WHERE analytics_order_facts.year = 2022 AND analytics_order_facts.month = 8 AND analytics_order_facts.region = 'South' AND analytics_order_facts.channel = 'marketplace' AND analytics_order_facts.payment_method = 'voucher' GROUP BY analytics_order_facts.customer_segment ORDER BY order_count ASC, analytics_order_facts.customer_segment ASC LIMIT 3
